<?php
namespace App\Modules\Sales\Domain\Models;
use App\Modules\Catalog\Domain\Models\ProductPresentation;use App\Modules\Orders\Domain\Models\SalesOrderLine;use Illuminate\Database\Eloquent\Attributes\Fillable;use Illuminate\Database\Eloquent\Concerns\HasUlids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasOne;
#[Fillable(['sale_id','sales_order_line_id','presentation_id','quantity','list_unit_price','applied_unit_price','discount','line_total','unit_cost','total_cost','price_reason'])]
class SaleLine extends Model {use HasUlids;public function sale():BelongsTo{return $this->belongsTo(Sale::class);}public function orderLine():BelongsTo{return $this->belongsTo(SalesOrderLine::class,'sales_order_line_id');}public function presentation():BelongsTo{return $this->belongsTo(ProductPresentation::class);}public function priceOverride():HasOne{return $this->hasOne(PriceOverride::class);}protected function casts():array{return ['quantity'=>'decimal:6','list_unit_price'=>'integer','applied_unit_price'=>'integer','discount'=>'integer','line_total'=>'integer','unit_cost'=>'integer','total_cost'=>'integer'];}}
